export function maskObservations<T extends MaskableMessage>(
    messages: readonly T[],
    options: ObservationMaskingOptions = DEFAULT_OBSERVATION_MASKING
): ObservationMaskingResult<T> {
    const unchanged = (reason?: ObservationMaskingResult<T>['skippedReason']): ObservationMaskingResult<T> => ({
        messages: [...messages], maskedCount: 0, charsRemoved: 0,
        totalObservationChars: 0, applied: false, skippedReason: reason
    });

    try {
        // Index every tool result in order, with its text size and the tool that produced it.
        const observations: { messageIndex: number; partIndex: number; chars: number; tool?: string }[] = [];
        const toolByCallId = new Map<string, string>();
        for (let m = 0; m < messages.length; m++) {
            for (const part of messages[m].parts) {
                if (part.kind === 'tool_call' && typeof part.callId === 'string' && typeof part.name === 'string') {
                    toolByCallId.set(part.callId, part.name as string);
                }
            }
        }
        let totalChars = 0;
        for (let m = 0; m < messages.length; m++) {
            const parts = messages[m].parts;
            for (let p = 0; p < parts.length; p++) {
                const part = parts[p];
                if (part.kind !== 'tool_result' || !Array.isArray(part.content)) continue;
                const chars = part.content.reduce(
                    (sum, child) => sum + (child.kind === 'text' && typeof child.text === 'string' ? child.text.length : 0), 0);
                totalChars += chars;
                observations.push({
                    messageIndex: m, partIndex: p, chars,
                    tool: part.callId ? toolByCallId.get(part.callId) : undefined
                });
            }
        }

        if (observations.length === 0) return { ...unchanged('nothing_maskable'), totalObservationChars: 0 };
        if (totalChars <= options.triggerChars) {
            return { ...unchanged('below_trigger'), totalObservationChars: totalChars };
        }

        // Everything before the boundary is masked. Quantising the boundary keeps the emitted prefix
        // byte-identical between strides instead of shifting it on every new tool call.
        const rawBoundary = Math.max(0, observations.length - Math.max(0, options.keepRecent));
        const boundary = Math.max(0, Math.floor(rawBoundary / Math.max(1, options.boundaryStride))
            * Math.max(1, options.boundaryStride));
        if (boundary === 0) return { ...unchanged('nothing_maskable'), totalObservationChars: totalChars };

        const targets = new Map<string, { chars: number; tool?: string }>();
        for (let i = 0; i < boundary; i++) {
            const observation = observations[i];
            if (observation.chars < options.minResultChars) continue;
            targets.set(`${observation.messageIndex}:${observation.partIndex}`,
                { chars: observation.chars, tool: observation.tool });
        }
        if (targets.size === 0) return { ...unchanged('nothing_maskable'), totalObservationChars: totalChars };

        let maskedCount = 0;
        let charsRemoved = 0;
        const rewritten = messages.map((message, m) => {
            let touched = false;
            const parts = message.parts.map((part, p) => {
                const target = targets.get(`${m}:${p}`);
                if (!target) return part;
                touched = true;
                maskedCount++;
                const placeholder = maskPlaceholder(target.chars, target.tool);
                charsRemoved += Math.max(0, target.chars - placeholder.length);
                // Text children collapse to one placeholder; non-text children are preserved as-is.
                const preserved = (part.content || []).filter(child => child.kind !== 'text');
                return { ...part, content: [{ kind: 'text' as const, text: placeholder }, ...preserved] };
            });
            return touched ? ({ ...message, parts } as T) : message;
        });

        return {
            messages: rewritten, maskedCount, charsRemoved,
            totalObservationChars: totalChars, applied: maskedCount > 0
        };
    } catch {
        return unchanged('failed');
    }
}

